@layer base {
    * {
        @apply border-border outline-ring/50;
    }
    body {
        @apply bg-background text-foreground;
    }

    h1,
    h2,
    h3,
    h4,
    h5,
    h6 {
        @apply font-semibold;
    }
}

@layer utilities {
    @keyframes fade-in {
        from {
            opacity: 0;
        }
        to {
            opacity: 1;
        }
    }

    @keyframes slide-down {
        from {
            transform: translateY(-10px);
            opacity: 0;
        }
        to {
            transform: translateY(0);
            opacity: 1;
        }
    }

    @keyframes scale-in {
        from {
            transform: scale(0.95);
            opacity: 0;
        }
        to {
            transform: scale(1);
            opacity: 1;
        }
    }

    .animate-fade-in {
        animation: fade-in 0.3s ease-in-out;
    }

    .animate-slide-down {
        animation: slide-down 0.3s ease-in-out;
    }

    .animate-scale-in {
        animation: scale-in 0.3s ease-in-out;
    }

    @keyframes marquee {
        0% {
            transform: translateX(0);
        }
        100% {
            transform: translateX(-50%);
        }
    }

    .animate-marquee {
        animation: marquee 45s linear infinite;
    }

    .animate-marquee.paused {
        animation-play-state: paused;
    }

    @keyframes gradient-x {
        0%,
        100% {
            background-position: 0% 50%;
        }
        50% {
            background-position: 100% 50%;
        }
    }

    .animate-gradient-x {
        background-size: 200% auto;
        animation: gradient-x 4s ease infinite;
    }

    @keyframes float {
        0%,
        100% {
            transform: translateY(0);
        }
        50% {
            transform: translateY(-12px);
        }
    }

    .animate-float {
        animation: float 6s ease-in-out infinite;
    }

    .animate-float-slow {
        animation: float 9s ease-in-out infinite;
    }

    @keyframes blob {
        0%,
        100% {
            transform: translate(0, 0) scale(1);
        }
        33% {
            transform: translate(20px, -30px) scale(1.1);
        }
        66% {
            transform: translate(-20px, 20px) scale(0.95);
        }
    }

    .animate-blob {
        animation: blob 14s ease-in-out infinite;
    }

    @keyframes shimmer {
        100% {
            transform: translateX(100%);
        }
    }

    .animate-shimmer {
        animation: shimmer 1.8s infinite;
    }

    @keyframes scroll-indicator {
        0% {
            transform: translateY(0);
            opacity: 1;
        }
        100% {
            transform: translateY(8px);
            opacity: 0;
        }
    }

    .animate-scroll-indicator {
        animation: scroll-indicator 1.6s ease-in-out infinite;
    }
}

import { createServerClient } from "@supabase/ssr"
import { NextResponse, type NextRequest } from "next/server"

export async function updateSession(request: NextRequest) {
  let supabaseResponse = NextResponse.next({
    request,
  })

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll()
        },
        setAll(cookiesToSet) {
          cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value))
          supabaseResponse = NextResponse.next({
            request,
          })
          cookiesToSet.forEach(({ name, value, options }) => supabaseResponse.cookies.set(name, value, options))
        },
      },
    },
  )

  const {
    data: { user },
  } = await supabase.auth.getUser()

  // Allow guest access to public pages and shopping flows
  const publicPaths = [
    "/",
    "/products",
    "/cart",
    "/checkout",
    "/order-success",
    '/refund-policy',
    "/blog",

  ]

  const isPublicPath = publicPaths.some(path =>
    request.nextUrl.pathname === path || request.nextUrl.pathname.startsWith(path + "/")
  )

  const isAuthPath = request.nextUrl.pathname.startsWith("/auth")

  // Only redirect to login for protected routes (admin, account) when not authenticated
  if (
    !user &&
    !isPublicPath &&
    !isAuthPath
  ) {
    const url = request.nextUrl.clone()
    url.pathname = "/auth/login"
    return NextResponse.redirect(url)
  }

  return supabaseResponse
}

import { createServerClient } from "@supabase/ssr"
import { NextResponse, type NextRequest } from "next/server"

export async function updateSession(request: NextRequest) {
  let supabaseResponse = NextResponse.next({
    request,
  })

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll()
        },
        setAll(cookiesToSet) {
          cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value))
          supabaseResponse = NextResponse.next({
            request,
          })
          cookiesToSet.forEach(({ name, value, options }) => supabaseResponse.cookies.set(name, value, options))
        },
      },
    },
  )

  const {
    data: { user },
  } = await supabase.auth.getUser()

  // Allow guest access to public pages and shopping flows
  const publicPaths = [
    "/",
    "/products",
    "/cart",
    "/checkout",
    "/order-success",
    '/refund-policy',
    "/blog",

  ]

  const pathname = request.nextUrl.pathname
  if (typeof pathname !== "string") {
    return supabaseResponse
  }

  const isPublicPath = publicPaths.some(path =>
    pathname === path || pathname.startsWith(path + "/")
  )

  const isAuthPath = pathname.startsWith("/auth")

  // Only redirect to login for protected routes (admin, account) when not authenticated
  if (
    !user &&
    !isPublicPath &&
    !isAuthPath
  ) {
    const url = request.nextUrl.clone()
    url.pathname = "/auth/login"
    return NextResponse.redirect(url)
  }

  return supabaseResponse
}

import { updateSession } from "@/lib/supabase/middleware"
        import { NextResponse, type NextRequest } from "next/server"

        export async function proxy(request: NextRequest) {
          // Allow public access to SEO files and API routes
          const publicPaths = [
            '/sitemap.xml',
            '/robots.txt',
            '/manifest.json',
            '/api/telegram',
              '/refund-policy',
              '/blog'
          ]

          if (publicPaths.some(path => request.nextUrl.pathname.startsWith(path))) {
            return NextResponse.next()
          }

          // Apply authentication for other routes
          return await updateSession(request)
        }

        export const config = {
          matcher: [
            "/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)",
          ],
        }

